def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    if n == 30:
        return 'D'
    if n == 31:
        return 'C'

    if n >= 32 and history[31][1] == 'C':
        last_me, last_opp = history[-1]
        if last_me == 'D' and last_opp == 'D':
            return 'C'
        return 'D'

    opp_D = 0
    cd = 0
    dc = 0
    dd = 0
    last_me, last_opp = history[-1]
    for me, opp in history:
        if opp == 'D':
            opp_D += 1
        if me == 'C' and opp == 'D':
            cd += 1
        elif me == 'D' and opp == 'C':
            dc += 1
        elif me == 'D' and opp == 'D':
            dd += 1

    if n >= 10 and opp_D > n * 0.8:
        return 'D'
    if n >= 15 and cd > n * 0.4 and dc < n * 0.1:
        return 'D'

    if last_me == 'D' and last_opp == 'D':
        dd_streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'D':
                dd_streak += 1
            else:
                break
        if dd_streak >= 2:
            return 'C'

    if last_opp == 'C':
        return 'C'

    if n < 10:
        return 'D'

    if opp_D <= n * 0.1:
        return 'C'

    if n < 30:
        if opp_D <= max(1, n // 10):
            return 'C'
        return 'D'

    if opp_D > n * 0.3:
        return 'D'

    if opp_D > n * 0.15:
        if last_me == 'D':
            return 'C'
        return 'D'

    return 'C'
